"""Portfolio simulation and trade tracking for technical strategy backtesting."""

from __future__ import annotations

import datetime
from collections.abc import Sequence
from dataclasses import dataclass, field


@dataclass
class SimulatedTrade:
    """Represents a simulated point-in-time trade generated by a technical signal or ranking."""

    security_id: int
    symbol: str
    entry_date: datetime.date
    exit_date: datetime.date
    entry_price: float
    exit_price: float
    return_pct: float
    benchmark_return_pct: float
    excess_return_pct: float
    holding_period_days: int
    candidate_category: str
    technical_score_at_entry: float
    is_win: bool = False

    def __post_init__(self) -> None:
        self.is_win = self.return_pct > 0.0


@dataclass
class PortfolioEquityPoint:
    """Snapshot of portfolio equity on a specific date."""

    date: datetime.date
    strategy_equity: float  # Normalized, starting at 100.0
    benchmark_equity: float  # Normalized, starting at 100.0
    drawdown_pct: float
    active_positions_count: int


@dataclass
class PortfolioSimulationResult:
    """Consolidated results of a historical portfolio backtest."""

    initial_capital: float
    final_strategy_equity: float
    final_benchmark_equity: float
    total_strategy_return_pct: float
    total_benchmark_return_pct: float
    total_trades: int
    winning_trades: int
    losing_trades: int
    win_rate_pct: float
    trades: list[SimulatedTrade] = field(default_factory=list)
    equity_curve: list[PortfolioEquityPoint] = field(default_factory=list)


class PortfolioTracker:
    """Simulates an equal-weighted portfolio rebalanced periodically based on candidate scores."""

    def __init__(self, initial_capital: float = 1000000.0) -> None:
        self.initial_capital = initial_capital
        self.strategy_equity = initial_capital
        self.benchmark_equity = initial_capital
        self.peak_equity = initial_capital
        self.trades: list[SimulatedTrade] = []
        self.equity_curve: list[PortfolioEquityPoint] = []

    def record_trades_batch(
        self,
        current_date: datetime.date,
        batch_trades: Sequence[SimulatedTrade],
        benchmark_period_return_pct: float,
    ) -> None:
        """Apply a batch of finished trades and record portfolio equity."""
        if not batch_trades:
            # Portfolio equity unchanged, benchmark tracks index
            bench_mult = 1.0 + (benchmark_period_return_pct / 100.0)
            self.benchmark_equity *= bench_mult
            dd = ((self.peak_equity - self.strategy_equity) / self.peak_equity) * 100.0 if self.peak_equity > 0 else 0.0
            self.equity_curve.append(
                PortfolioEquityPoint(
                    date=current_date,
                    strategy_equity=round(self.strategy_equity, 2),
                    benchmark_equity=round(self.benchmark_equity, 2),
                    drawdown_pct=round(dd, 2),
                    active_positions_count=0,
                )
            )
            return

        # Equal weight among batch trades
        avg_trade_return = sum(t.return_pct for t in batch_trades) / len(batch_trades)
        strat_mult = 1.0 + (avg_trade_return / 100.0)
        bench_mult = 1.0 + (benchmark_period_return_pct / 100.0)

        self.strategy_equity *= strat_mult
        self.benchmark_equity *= bench_mult

        if self.strategy_equity > self.peak_equity:
            self.peak_equity = self.strategy_equity

        dd = ((self.peak_equity - self.strategy_equity) / self.peak_equity) * 100.0 if self.peak_equity > 0 else 0.0

        for t in batch_trades:
            self.trades.append(t)

        self.equity_curve.append(
            PortfolioEquityPoint(
                date=current_date,
                strategy_equity=round(self.strategy_equity, 2),
                benchmark_equity=round(self.benchmark_equity, 2),
                drawdown_pct=round(dd, 2),
                active_positions_count=len(batch_trades),
            )
        )

    def summarize(self) -> PortfolioSimulationResult:
        """Generate final portfolio backtest report."""
        total_trades = len(self.trades)
        wins = sum(1 for t in self.trades if t.is_win)
        losses = sum(1 for t in self.trades if not t.is_win)
        win_rate = (wins / total_trades * 100.0) if total_trades > 0 else 0.0

        strat_ret = ((self.strategy_equity - self.initial_capital) / self.initial_capital) * 100.0
        bench_ret = ((self.benchmark_equity - self.initial_capital) / self.initial_capital) * 100.0

        return PortfolioSimulationResult(
            initial_capital=self.initial_capital,
            final_strategy_equity=round(self.strategy_equity, 2),
            final_benchmark_equity=round(self.benchmark_equity, 2),
            total_strategy_return_pct=round(strat_ret, 2),
            total_benchmark_return_pct=round(bench_ret, 2),
            total_trades=total_trades,
            winning_trades=wins,
            losing_trades=losses,
            win_rate_pct=round(win_rate, 2),
            trades=self.trades,
            equity_curve=self.equity_curve,
        )
